<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;
class UpbringingAnnualReport extends Page{protected static ?string $navigationIcon='heroicon-o-document-report';protected static ?string $navigationLabel='Годовой отчёт';protected static ?string $navigationGroup='Воспитательная работа';protected static string $view='filament.pages.upbringing-annual-report';public array $stats=[];public array $directions=[];public function mount():void{$p=request()->attributes->get('academic_period');if(!$p)return;$e=DB::table('upbringing_events')->where('academic_period_id',$p->id)->select('direction',DB::raw('COUNT(*) total'),DB::raw("SUM(CASE WHEN status='completed' THEN 1 ELSE 0 END) completed"),DB::raw('SUM(COALESCE(participants_count,0)) participants'))->groupBy('direction')->get();$this->directions=$e->map(fn($x)=>(array)$x)->all();$this->stats=['events'=>$e->sum('total'),'completed'=>$e->sum('completed'),'participants'=>$e->sum('participants'),'achievements'=>DB::table('student_achievements')->where('academic_period_id',$p->id)->count(),'cases'=>DB::table('student_support_cases')->where('academic_period_id',$p->id)->count(),'cases_closed'=>DB::table('student_support_cases')->where('academic_period_id',$p->id)->where('status','closed')->count(),'meetings'=>DB::table('parent_meetings')->where('academic_period_id',$p->id)->count(),'councils'=>DB::table('prevention_councils')->where('academic_period_id',$p->id)->count(),'clubs'=>DB::table('student_clubs')->where('academic_period_id',$p->id)->where('active',1)->count(),'appeals'=>DB::table('upbringing_appeals')->where('academic_period_id',$p->id)->count()];}public static function canAccess():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->canDo('upbringing.view'));}}